  const render=()=>{addStyles();const s=strings[locale()];let section=document.getElementById('poster-downloads');if(!section){section=document.createElement('section');section.className='panel poster-download';section.id='poster-downloads';const target=document.querySelector('.cases')?.closest('.panel');if(target)target.before(section);else document.querySelector('main.shell')?.append(section)}section.setAttribute('aria-labelledby','poster-downloads-title');const cards=posters.map(([file],i)=>{const label=s.labels[i],url=base+file;return '<article class="poster-download-card"><a href="'+url+'" target="_blank" rel="noopener" aria-label="'+s.preview+'：'+label+'"><img src="'+url+'" alt="'+label+'｜'+s.title+'" loading="lazy" width="1024" height="1536"></a><div class="poster-download-copy"><h3>'+label+'</h3><p>'+s.meta+'</p><div class="poster-download-actions"><a href="'+url+'" target="_blank" rel="noopener">'+s.preview+'</a><a href="'+url+'" download="'+file+'">'+s.download+'</a></div></div></article>'}).join('');section.innerHTML='<h2 id="poster-downloads-title">'+s.title+'</h2><p class="lede">'+s.lead+'</p><div class="poster-download-grid">'+cards+'</div>'};
